import subprocess

class GitWrapper:
    def __init__(self, repo_path):
        self.repo_path = repo_path

    def run_git_command(self, command, *args):
        full_command = ['git', '-C', self.repo_path] + [command] + list(args)
        try:
            result = subprocess.run(full_command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            return result.stdout
        except subprocess.CalledProcessError as e:
            print(f"Git command failed: {e.stderr}")
            raise

    def clone_repo(self, url):
        self.run_git_command('clone', url)

    def pull_repo(self):
        self.run_git_command('pull')

    def push_repo(self):
        self.run_git_command('push')

    def add_all_files(self):
        self.run_git_command('add', '.')

    def commit_changes(self, message):
        self.run_git_command('commit', '-m', message)

